create table public.market_references (
    item_key text not null check (item_key ~ '^(card|product):.+$'),
    source text not null,
    quote_kind text not null check (quote_kind in ('snapshot', 'market', 'estimate', 'listing')),
    amount numeric(12, 2) not null check (amount > 0),
    currency text not null default 'USD' check (currency = 'USD'),
    observed_on date not null,
    basis text,
    source_url text check (source_url is null or source_url like 'https://%'),
    primary key (item_key, source, quote_kind)
);

alter table public.market_references enable row level security;
revoke all on public.market_references from public, anon, authenticated;
grant select on public.market_references to anon, authenticated;

create policy "Public market references can be read"
on public.market_references for select
to anon, authenticated
using (true);

-- Catalog snapshots, explicitly labeled comparables, and TCGplayer market data via TCGCSV.
-- Keep the same starting dataset in the iOS bundle for offline access.
insert into public.market_references (
    item_key, source, quote_kind, amount, observed_on, basis, source_url
)
select entries.key, quote.source, quote.quote_kind, quote.amount,
       quote.observed_on, quote.basis, quote.source_url
from jsonb_each($seed$
