$seed$::jsonb) as entries
cross join lateral jsonb_to_recordset(entries.value) as quote (
    source text, quote_kind text, amount numeric, observed_on date, basis text, source_url text
)
on conflict (item_key, source, quote_kind) do update
set amount = excluded.amount,
    observed_on = excluded.observed_on,
    basis = excluded.basis,
    source_url = excluded.source_url
where market_references.observed_on <= excluded.observed_on;
